import React, { useRef, useState } from "react";
import TimelineScroller from "./components/TimelineScroller";
import VideoPlayer from "./components/VideoPlayer";

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

export default function App() {
  const fileInputRef = useRef(null);
  const videoRef = useRef(null);

  const [videoSrc, setVideoSrc] = useState("");
  const [duration, setDuration] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [loading, setLoading] = useState(false);
  const [uploadError, setUploadError] = useState("");

  const openFilePicker = () => fileInputRef.current?.click();

  const handleFileChange = async (event) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setLoading(true);
    setUploadError("");

    try {
      const formData = new FormData();
      formData.append("video", file);

      const response = await fetch("http://localhost:5000/upload", {
        method: "POST",
        body: formData,
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || "Upload failed");
      }

      const previewUrl = `http://localhost:5000${data.preview_video}`;

      setVideoSrc(previewUrl);
      setCurrentTime(0);
      setDuration(0);
    } catch (err) {
      setUploadError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleTogglePlay = () => {
    const video = videoRef.current;
    if (!video) return;

    if (video.paused) video.play();
    else video.pause();
  };

  const handleSeek = (time) => {
    const video = videoRef.current;
    if (!video || duration <= 0) return;

    const t = clamp(time, 0, duration);
    video.currentTime = t;
    setCurrentTime(t);
  };

  return (
    <div className="min-h-screen bg-[#0f0f0f] text-white py-10">
      <div className="mx-auto max-w-[1200px] px-4">

        {/* 🔷 HEADER */}
        <div className="mb-6 rounded-[28px] border border-white/10 bg-slate-950/95 p-6 shadow-[0_24px_80px_rgba(0,0,0,0.2)]">
          <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
            <div>
              <h1 className="text-2xl font-semibold">Video Tampering Detection</h1>
              <p className="text-sm text-slate-400 mt-2">
                Upload a video to detect tampered segments and review results.
              </p>
            </div>

            <button
              onClick={openFilePicker}
              className="rounded-full border border-slate-700 bg-slate-900 px-4 py-2 text-sm font-semibold hover:border-slate-500"
            >
              Upload Video
            </button>
          </div>
        </div>

        {/* 🔥 MAIN LAYOUT */}
        <div className="grid gap-6 lg:grid-cols-[3fr_1fr] items-start">

          {/* LEFT SIDE */}
          <div className="flex flex-col gap-4">

            {/* 🎥 VIDEO PANEL */}
            <div className="h-[520px] overflow-hidden rounded-[28px] border border-white/10 bg-slate-950/95 shadow-[0_24px_80px_rgba(0,0,0,0.2)] p-5">
              <VideoPlayer
                ref={videoRef}
                src={videoSrc}
                isPlaying={isPlaying}
                currentTime={currentTime}
                onTogglePlay={handleTogglePlay}
                onTimeUpdate={setCurrentTime}
                onDurationChange={setDuration}
                onPlay={() => setIsPlaying(true)}
                onPause={() => setIsPlaying(false)}
                hasVideo={!!videoSrc}
              />
            </div>

            {/* ⏱ TIMELINE BELOW */}
            <div className="rounded-[28px] border border-white/10 bg-slate-950/95 p-4">
              <TimelineScroller
                duration={duration}
                currentTime={currentTime}
                loading={loading}
                onSeek={handleSeek}
                onUploadClick={openFilePicker}
              />
            </div>

          </div>

          {/* 📊 RESULT PANEL */}
          <div className="h-[520px] flex flex-col rounded-[28px] border border-white/10 bg-slate-950/95 p-5 shadow-[0_24px_80px_rgba(0,0,0,0.2)]">

            <div className="flex-1 flex flex-col justify-between">

              <div>
                <h2 className="text-xl font-semibold">Analysis</h2>
                <p className="text-sm text-slate-400 mt-2">
                  View tampering detection results and statistics.
                </p>
              </div>

              <div className="space-y-4">
                <div className="bg-slate-900 p-4 rounded-xl">
                  <div className="text-sm text-slate-400">Duration</div>
                  <div className="text-lg font-semibold">
                    {duration
                      ? `${Math.floor(duration / 60)
                          .toString()
                          .padStart(2, "0")}:${Math.floor(duration % 60)
                          .toString()
                          .padStart(2, "0")}`
                      : "00:00"}
                  </div>
                </div>

                <div className="bg-slate-900 p-4 rounded-xl">
                  <div className="text-sm text-slate-400">Status</div>
                  <div className="text-lg font-semibold">
                    {videoSrc ? "Ready" : "Waiting for upload"}
                  </div>
                </div>
              </div>

              <div className="space-y-3">
                <button
                  disabled={!videoSrc}
                  className="w-full bg-slate-900 py-3 rounded-full hover:bg-slate-800"
                >
                  View Results
                </button>

                <button
                  disabled={!videoSrc}
                  className="w-full bg-white/10 py-3 rounded-full hover:bg-white/20"
                >
                  Download Report
                </button>
              </div>

            </div>
          </div>

        </div>

      </div>

      {/* 📂 FILE INPUT */}
      <input
        type="file"
        accept="video/*"
        ref={fileInputRef}
        className="hidden"
        onChange={handleFileChange}
      />

      {/* ❗ ERROR */}
      {uploadError && (
        <div className="mx-auto mt-4 max-w-[1200px] text-red-400 text-sm">
          {uploadError}
        </div>
      )}
    </div>
  );
}
